	public KPITest() {
		subscriber = new KPISubscriber();
	}

	// test methods
	@Test
	/*
	 * Initiate KPITest.
	 */
	public void startTest() throws Throwable {
		try {
			LOGGER.info("**********************************************************");
			LOGGER.info("Beginning test on KPI...");
			LOGGER.info("**********************************************************\n");
			
			// ---------------------------------------------
			// jumpstart process
			// ---------------------------------------------
			jumpStart();
			
		} catch (Throwable e) {
			throw e;
		} finally {
		}
	}

	/** 
	 * jumpstart the process by instantiating2 KPI
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		kPIId = KPIService.getKPIInstance()
		.createKPI( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		KPIService.getKPIInstance()
				.createKPI( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.kPISubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for KPI : " + successValue.getKPIId());
							  if (successValue.getKPIId().equals(kPIId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfKPIList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("KPI test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on kPI consumed")
					);
			subscriber.kPISubscribe( kPIId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for KPI : " + successValue.getKPIId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfKPIList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on kPI for kPIId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a KPI. 
	 */
	protected KPI read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created KPI" );

		KPI entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read KPI with primary key" );
		msg.append( kPIId );
		
		KPIFetchOneSummary fetchOneSummary = new KPIFetchOneSummary( kPIId );

		try {
			entity = KPIService.getKPIInstance().getKPI( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found KPI " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a KPI.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a KPI." );

		StringBuilder msg = new StringBuilder( "Failed to update a KPI : " );        
		KPI entity = read();
		UpdateKPICommand command = generateUpdateCommand();
		command.setKPIId(entity.getKPIId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created KPI." );

			// for use later on...
			kPIId = entity.getKPIId();

			KPIService proxy = KPIService.getKPIInstance();  

			proxy.updateKPI( command ).get();

			LOGGER.info( "-- Successfully saved KPI - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + kPIId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a KPI.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created KPI." );

		KPI entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read KPI with id " + kPIId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read KPI with id " + kPIId );

			throw e;
		}

		try{
			KPIService.getKPIInstance().delete( new DeleteKPICommand( entity.getKPIId() ) ).get();
			LOGGER.info( "-- Successfully deleted KPI with id " + kPIId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete KPI with id " + kPIId );

			throw e;
		}
	}

	/**
	 * get all KPIs.
	 */
	protected List<KPI> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of KPIs:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all KPI : " );        
		List<KPI> collection  = new ArrayList<>();

		try {
			// call the static get method on the KPIService
			collection = KPIService.getKPIInstance().getAllKPI();
			assertNotNull( collection, "An Empty collection of KPI was incorrectly returned.");
			
			// Now print out the values
			KPI entity = null;            
			Iterator<KPI> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getKPIId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

	/**
	 * Assigns a common log handler for each test class in the suite 
	 * in the event log output needs to go elsewhere
	 * 
	 * @param		handler	Handler
	 * @return		KPITest
	 */
	protected KPITest setHandler(Handler handler) {
		if ( handler != null )
			LOGGER.addHandler(handler); 
		return this;
	}

	/**
	 * Returns a new populated KPI
	 * 
	 * @return CreateKPICommand alias
	 */
	protected CreateKPICommand generateNewCommand() {
        CreateKPICommand command = new CreateKPICommand( null,  java.math.BigDecimal.ZERO,  MetricType.values()[0] );
		
		return( command );
	}

		/**
		 * Returns a new populated KPI
		 * 
		 * @return UpdateKPICommand alias
		 */
	protected UpdateKPICommand generateUpdateCommand() {
	        UpdateKPICommand command = new UpdateKPICommand( null,  java.math.BigDecimal.ZERO,  null,  MetricType.values()[0] );
			
			return( command );
		}
